/* Scenario-led visuals. Generated editorial imagery is illustrative, not a real listing photo. */
const media={hen:'assets/hen.webp',workspace:'assets/workspace.webp',village:'assets/village.webp',coffee:'assets/coffee.webp',harvest:'assets/harvest.webp',tea:'assets/tea.webp',meeting:'assets/meeting.webp',bamboo:'assets/bamboo.webp'};
const photo=(key,alt,cls='',eager=false)=>`<img class="scene-photo ${cls}" src="${media[key]}" alt="${esc(alt)}" loading="${eager?'eager':'lazy'}" decoding="async">`;
const photoLabels={hen:'林下散养鸡',workspace:'竹林旁的共享办公空间',village:'山间村庄与乡野田园',coffee:'乡村咖啡馆的创意交流',harvest:'稻田里的秋收体验',tea:'带着晨露的茶芽',meeting:'乡村独立会议空间',bamboo:'阳光洒落的竹林步道'};
const visualBase={home,activityPage,adoptModal,action,render,loginPage,travelPage,userPage,resourcePage};
const adoptionProjects=[
 {id:'hen',name:'认养一只鸡，收获一份牵挂',short:'林下散养鸡 · 小栗',image:'hen',type:'林下散养',price:136,unit:'120 天',code:'HEN-001',place:'安吉 · 林下小院',species:'本地土鸡',age:'示例档案 · 第 45 天',progress:38,host:'林下农场 · 示例农户',desc:'与远方的一只鸡建立连接，在日常养护记录里，感受乡村生活的真实节奏。',facts:[['认养周期','120 天'],['养护方式','农户日常照料'],['生长阶段','成长中']],logs:[['DAY 45','林间散步的一天','今日示例：在林下活动区觅食，农户完成饮水与环境检查。'],['DAY 38','给小院添一点新鲜','今日示例：清理活动区域，补充日常饲料。'],['DAY 30','认识你的乡村新朋友','建立数字档案，记录认养对象与养护安排。']]},
 {id:'rice',name:'认养一方稻田，等待金黄',short:'共享稻田 · 秋日来信',image:'harvest',type:'四季农田',price:299,unit:'一季',code:'RICE-020',place:'余村 · 共享农田',species:'水稻 · 20 平方米',age:'示例档案 · 灌浆期',progress:72,host:'田间共创小组 · 示例农户',desc:'从青绿到金黄，跟着农户的记录，见证一季稻米的生长。',facts:[['认养面积','20 平方米'],['养护方式','农户统一耕作'],['生长阶段','等待成熟']],logs:[['记录 03','稻穗慢慢低下头','示例观察：稻穗逐渐饱满，农户检查田间水位。'],['记录 02','田间的一次巡护','示例观察：查看叶色与灌溉设施。'],['记录 01','把期待种进田里','建立认养档案，记录地块与养护计划。']]},
 {id:'tea-tree',name:'认养一棵茶树，收藏春天',short:'安吉白茶树 · 一芽一叶',image:'tea',type:'茶园认养',price:199,unit:'一季',code:'TEA-016',place:'安吉 · 山间茶园',species:'白茶树 · 1 棵',age:'示例档案 · 日常养护',progress:55,host:'山间茶事 · 示例农户',desc:'一芽一叶，一季一约。让一杯茶，连接你和远方的山野。',facts:[['认养对象','1 棵茶树'],['养护方式','茶农日常照料'],['生长阶段','枝叶养护']],logs:[['记录 03','叶片上的晨露','示例观察：记录叶片状态与土壤情况。'],['记录 02','一段属于山间的安静','示例观察：茶园日常巡护与除草。'],['记录 01','与一棵茶树结缘','建立茶树档案，介绍本季养护计划。']]}
];
