spaceCard=function(s){const k=s.id==='bamboo'?'workspace':s.id==='field'?'coffee':'meeting';return `<article class="card workspace-card"><div class="art">${photo(k,photoLabels[k])}<span class="artlabel">${s.area}</span><span class="image-corner">${icon('pin')}${s.place}</span></div><div class="cardbody"><div class="microline"><span>WORKSPACE / ${s.id==='bamboo'?'01':s.id==='field'?'02':'03'}</span><span class="signal">▂▄▆ ${s.net}</span></div><h3>${s.name}</h3><p>${s.desc}</p>${tags(s.tags.slice(0,2))}<div class="cardfoot"><span class="price">¥ ${s.price}<small> / 天 · 示例</small></span>${btn('去选座 '+icon('arrow'),'book','',`data-id="${s.id}"`)}</div></div></article>`};
activityCard=function(a){const k=a.type==='自然户外'?'bamboo':a.type==='农事体验'?'harvest':'coffee';return `<article class="card experience-card"><div class="art">${photo(k,photoLabels[k])}<span class="artlabel">${a.type}</span><div class="date-sticker"><strong>${eventDate(a).slice(8)}</strong><span>${eventDate(a).slice(5,7)} 月</span></div></div><div class="cardbody"><div class="microline">${a.type==='自然户外'?'OUTDOOR':a.type==='农事体验'?'FARM LIFE':'CO-CREATE'} EXPERIENCE</div><h3>${esc(a.name)}</h3><p>${esc(a.time)} · ${esc(a.place)}</p><div class="cardfoot"><span class="price">${a.price?'¥ '+a.price:'免费'}<small> / 体验</small></span>${btn(state.events.includes(a.id)?'已报名 · 查看':'看看活动','event','secondary',`data-id="${a.id}"`)}</div></div></article>`};
home=function(){if(state.profile.role!=='数字游民')return visualBase.home();return `${heading(`你好，${esc(state.profile.name)}。换个地方，打开生活。`,'工作在线，生活在野。今天想从哪件小事开始？',`<div class="connection-badge"><i></i> CONNECT TO THE COUNTRYSIDE</div>`)}<section class="digital-hero"><div class="digital-herophoto">${photo('village',photoLabels.village,'',true)}</div><div class="digital-herocopy"><div class="hero-kicker"><span>乡野生活，正在连接</span><b>VOL. 01</b></div><h2>把工位搬进自然，<br>让生活<span>自由生长。</span></h2><p>一台电脑，一片山野，一群同频的人。<br>你的下一种生活，从这里开始。</p><div class="hero-actions"><button class="btn" data-go="map">探索我的下一站 ${icon('arrow')}</button><button class="hero-link" data-action="open-adoptions">认养一份小美好 ↗</button></div><div class="hero-coordinate">30° N / 119° E <span>浙江 · 安吉 / 示意坐标</span></div></div><div class="float-note"><span class="floating-icon">${icon('leaf')}</span><div><small>A NEW WAY TO LIVE</small><b>保持连接，也保持自由</b></div><span class="note-orbit"></span></div></section><div class="sectiontitle"><h2>一站连接，你的乡野日常</h2><small>WORK · EXPLORE · SHARE · GROW</small></div><div class="modules">${modules.map((m,i)=>`<button class="module digital-module tone-${i}" data-go="${m[0]}"><span class="moduleicon">${icon(m[0])}</span><b>${m[1]}</b><small>${m[2]}</small><span class="module-arrow">↗</span></button>`).join('')}</div><div class="twocol feature-layout"><section><div class="sectiontitle"><div><span class="section-kicker">WORK IN NATURE</span><h2>有风景，也有生产力。</h2></div><button class="textbtn" data-go="desk">找个好工位 ${icon('arrow')}</button></div><div class="grid two">${spaces.slice(0,2).map(spaceCard).join('')}</div></section><section><div class="sectiontitle"><div><span class="section-kicker">GROW A CONNECTION</span><h2>认养一份小牵挂</h2></div></div><article class="mini-adoption"><div class="mini-adoption-photo">${photo('hen',photoLabels.hen)}<span class="artlabel warm">NEW · 林下小院</span></div><div class="mini-adoption-body"><span class="microline">DIGITAL FARM / HEN-001</span><h3>你在认真工作，<br>小栗在认真长大。</h3><p>认养一只鸡，拥有一份远方的日常。</p><div class="cardfoot"><span class="price">¥ 136<small> / 120 天 · 示例</small></span>${btn('认识小栗 ↗','adopt','',`data-id="hen"`)}</div></div></article></section></div><div class="sectiontitle"><div><span class="section-kicker">MORE THAN A PLACE TO STAY</span><h2>一起做点有意思的事。</h2></div><button class="textbtn" data-go="calendar">发现更多 ${icon('arrow')}</button></div><div class="grid">${activities.slice(0,3).map(activityCard).join('')}</div><div class="portfolio-strip"><span>${icon('community')} 让个体的技能，连接乡村的可能。</span><button class="textbtn" data-go="community">走进邻里圈 ↗</button></div>`};
function adoptionCard(a){let owned=state.adoptions.includes(a.id);return `<article class="adoption-card"><div class="adoption-image">${photo(a.image,photoLabels[a.image])}<span class="artlabel ${a.id==='hen'?'warm':''}">${a.type}</span><span class="adoption-id">${a.code}</span></div><div class="adoption-content"><div class="microline">${a.place}</div><h3>${a.name}</h3><p>${a.desc}</p><div class="adoption-facts">${a.facts.slice(0,2).map(f=>`<div><small>${f[0]}</small><b>${f[1]}</b></div>`).join('')}</div><div class="cardfoot"><span class="price">¥ ${a.price}<small> / ${a.unit} · 示例</small></span>${btn(owned?'打开我的档案':'了解认养 ↗','adopt',owned?'soft':'',`data-id="${a.id}"`)}</div></div></article>`}
function adoptionPage(){return `<div class="adoption-intro"><div><div class="eyebrow">A LITTLE CARE, A LIVING CONNECTION</div><h2>认养的，是一份<span>与乡村的连接。</span></h2><p>从一只鸡、一方稻田到一棵茶树，让远方的生长成为日常的小期待。</p></div><div class="adoption-path"><span>01 选择认养</span><i>→</i><span>02 建立档案</span><i>→</i><span>03 关注生长</span></div></div><div class="adoption-grid">${adoptionProjects.map(adoptionCard).join('')}</div><div class="scene-disclosure">场景图片为 AI 生成的展示素材；档案、价格与养护记录为演示内容，不代表真实农场的实时状态。</div>`}
activityPage=function(){if(state.profile.role!=='数字游民')return visualBase.activityPage();let v=tab||'乡村活动';return `${heading('把日子过得有意思，也有点不一样。','走进一场活动，或者认养一份生长。你与乡村的故事，从参与开始。')}${tabs(['乡村活动','云认养','我的参与'])}${v==='云认养'?adoptionPage():v==='我的参与'?`<div class="participation-layout"><section class="panel"><div class="sectiontitle" style="margin-top:0"><h2>我的活动</h2><span class="tag">${state.events.length} 场期待</span></div>${state.events.length?state.events.map(activityRecord).join(''):empty('下一次相遇，也许就在一场活动里。')}</section><section><div class="sectiontitle" style="margin-top:0"><h2>我的数字农场</h2><span class="tag">${state.adoptions.length} 份牵挂</span></div>${state.adoptions.length?state.adoptions.map(id=>{const a=adoptionProjects.find(a=>a.id===id);return a?`<article class="owned-adoption">${photo(a.image,photoLabels[a.image])}<div><span class="microline">${a.code}</span><h3>${a.short}</h3><p>${a.age}</p>${btn('查看生长档案','adopt','soft tiny',`data-id="${id}"`)}</div></article>`:''}).join(''):empty('还没有认养，从认识一只鸡开始吧。')}</section></div>`:`<div class="experience-intro"><div><span class="eyebrow">OFFLINE IS THE NEW LUXURY</span><h2>暂时离线，让真实的相遇上线。</h2><p>竹林走走、喝杯咖啡、体验秋收，总有一种方式让你融入这里。</p></div><button class="btn secondary" data-action="open-adoptions">去看看云认养 ↗</button></div><div class="filters">${['全部','自然户外','社群共创','农事体验'].map(t=>`<button class="chip ${filter===t?'selected':''}" data-filter="${t}">${t}</button>`).join('')}</div><div class="grid">${activities.filter(a=>filter==='全部'||a.type===filter).map(activityCard).join('')}</div>`}`};
adoptModal=function(id){const a=adoptionProjects.find(a=>a.id===id);if(!a)return;let owned=state.adoptions.includes(id);modal(a.short,`<div class="farm-cover">${photo(a.image,photoLabels[a.image],'',true)}<span class="farm-cover-label">${a.code}<br>DIGITAL ADOPTION FILE</span></div><div class="farm-profile"><div><span class="microline">${a.place}</span><h3>${a.species}</h3></div><span class="tag">${owned?'已建立认养档案':'等待一份连接'}</span></div><div class="farm-metrics">${a.facts.map(f=>`<div><small>${f[0]}</small><b>${f[1]}</b></div>`).join('')}</div><div class="farm-tabs"><button class="farm-tab active" data-farmtab="story">生长动态</button><button class="farm-tab" data-farmtab="care">养护计划</button><button class="farm-tab" data-farmtab="terms">认养说明</button></div><div id="farm-panel">${farmPanel(a,'story')}</div><p class="help">图片为 AI 场景素材，记录为非实时示例。保存认养意向不会付款，也不承诺收益。</p>`,owned?btn('取消认养意向','cancel-adopt','secondary',`data-id="${id}"`):btn(`¥ ${a.price} / ${a.unit} · 保存认养意向`,'confirm-adopt','',`data-id="${id}"`));$('#modal').classList.add('farm-dialog');$('#modal').querySelectorAll('[data-farmtab]').forEach(b=>b.onclick=()=>{$('#modal').querySelectorAll('[data-farmtab]').forEach(t=>t.classList.toggle('active',t===b));$('#farm-panel').innerHTML=farmPanel(a,b.dataset.farmtab)})};
function farmPanel(a,view){if(view==='care')return `<div class="care-list"><div><span>01</span><section><h3>定期巡护</h3><p>${a.id==='hen'?'检查饮水、饲料与活动环境，观察日常状态。':'观察土壤、叶片与水分，记录日常养护情况。'}</p></section></div><div><span>02</span><section><h3>记录变化</h3><p>由农户更新图片和养护说明，让每一份照料都有迹可循。</p></section></div><div><span>03</span><section><h3>收获前沟通</h3><p>认养周期结束前，确认后续安排；以真实项目协议为准。</p></section></div></div>`;if(view==='terms')return `<div class="summary">认养对象：${a.species}<br>展示周期：${a.unit}<br>示例价格：¥${a.price}<br>当前实际支付：¥0 · 当前实际收益：¥0<br>本页仅演示认养意向与数字档案，不签订合同、不产生实际交易。图片不构成真实项目证明。</div>`;return `<div class="farm-progress"><div><b>${a.age}</b><small>示例进度 ${a.progress}%</small></div><div class="growth"><i style="width:${a.progress}%"></i></div></div><div class="farm-timeline">${a.logs.map(l=>`<div><span>${l[0]}</span><section><h3>${l[1]}</h3><p>${l[2]}</p></section></div>`).join('')}${state.approvals.filter(r=>r.kind==='认养动态'&&r.status==='已通过'&&r.adoptionId===a.id).map(r=>`<div><span>农户更新</span><section><h3>${esc(r.title)}</h3><p>${esc(r.desc)}</p></section></div>`).join('')}</div>`}
const originalModal=modal;
modal=function(...args){$('#modal').classList.remove('farm-dialog');originalModal(...args)};
// Preserve all task flows while assigning each scene an appropriate image.
function decorateScenes(){
 document.body.dataset.view=page;document.body.dataset.role=state.profile.role;
 const art=$('.heroart');if(art){art.innerHTML=photo(isReviewer()?'meeting':state.profile.role==='企业'?'coffee':'village','乡村生活场景','',true);art.classList.add('photo-heroart')}
 const loginArt=$('.loginart');if(loginArt){loginArt.innerHTML=photo('village',photoLabels.village,'',true);loginArt.classList.add('photo-loginart')}
 if(page==='map'){
  const cards=document.querySelectorAll('.content .grid .card');cards.forEach((card,i)=>{const k=['village','bamboo','harvest'][i%3],a=card.querySelector('.art');if(a)a.innerHTML=photo(k,photoLabels[k])+`<span class="artlabel">${villages[i]?.tag||'在地发现'}</span>`});
  const planning=$('.accentpanel .art');if(planning)planning.innerHTML=photo('bamboo',photoLabels.bamboo);
  document.querySelectorAll('.content .grid .panel .avatar').forEach((a,i)=>{a.classList.add('creative-avatar');a.dataset.tone=i%3});
 }
 if(page==='desk'){document.querySelectorAll('.content .grid .card').forEach((card,i)=>{if(card.classList.contains('workspace-card'))return;const k=['workspace','coffee','meeting'][i%3],a=card.querySelector('.art');if(a)a.innerHTML=photo(k,photoLabels[k])})}
 if(page==='box'){
  document.querySelectorAll('.content .grid>.panel').forEach((p,i)=>{p.classList.add('resource-visual-card');let h=p.querySelector('h3')?.textContent||'',kind=/摄影|相机/.test(h)?'camera':/设计|包装/.test(h)?'design':/车/.test(h)?'bike':/打印/.test(h)?'printer':/网络/.test(h)?'wifi':/投影/.test(h)?'projector':'monitor';if(!p.querySelector('.resource-object'))p.insertAdjacentHTML('afterbegin',resourceObject(kind));});
 }
 if(page==='community'){
  document.querySelectorAll('.post').forEach((p,i)=>{p.classList.add('visual-post');if(i<2){const k=i===0?'bamboo':'workspace';const foot=p.querySelector('.postfoot');foot?.insertAdjacentHTML('beforebegin',`<div class="post-scene">${photo(k,i===0?'乡野散步的场景配图':'乡村公共阅读空间的场景配图')}<span>场景示意</span></div>`)}});
 }
 const foot=$('.footer');if(foot&&!foot.querySelector('.visual-disclosure'))foot.insertAdjacentHTML('beforeend','<span class="visual-disclosure">AI 场景图片 · 非真实项目照片</span>');
}
function resourceObject(kind){const draw={monitor:'<rect x="42" y="26" width="116" height=" seventy" rx="8"/><path d="M100 98v20m-30 0h60"/>',camera:'<rect x="42" y="48" width="116" height="68" rx="12"/><circle cx="104" cy="82" r="24"/><circle cx="104" cy="82" r="13"/><path d="M66 48l8-16h39l9 16m16 15h7"/>',bike:'<circle cx="51" cy="105" r="27"/><circle cx="153" cy="105" r="27"/><path d="m51 105 30-48 30 48H51l19-34h69m-28 34 24-56h15m-77 8h20"/>',design:'<rect x="57" y="28" width="86" height="98" rx="9"/><path d="M72 47h54M72 60h30M72 113l41-41 14 14-40 40M113 72l10-10 14 14-10 10"/>',printer:'<rect x="41" y="60" width="118" height="48" rx="10"/><path d="M63 60V28h74v32M62 92h76v40H62zm73-16h7"/>',wifi:'<path d="M37 61a91 91 0 0 1 126 0M55 82a65 65 0 0 1 90 0m-71 20a35 35 0 0 1 52 0"/><circle cx="100" cy="122" r="6"/>',projector:'<rect x="40" y="46" width="120" height="75" rx="12"/><circle cx="126" cy="82" r="23"/><path d="M53 69h33m-33 13h25m-25 13h25"/>'};return `<div class="resource-object object-${kind}"><div class="object-orbit"></div><svg viewBox="0 0 200 155" aria-hidden="true">${(draw[kind]||draw.monitor).replace(' seventy','72')}</svg><span>${{camera:'CREATE',bike:'RIDE',design:'CO-CREATE',printer:'PRINT',wifi:'CONNECT',projector:'PRESENT',monitor:'WORK'}[kind]}</span></div>`}
render=function(){visualBase.render();decorateScenes()};
loginPage=function(){visualBase.loginPage();decorateScenes()};
action=function(a,d){if(a==='open-adoptions'){go('calendar','云认养');return}if(a==='growth'){
 visualBase.action(a,d);const f=$('#approval-form');if(f){f.insertAdjacentHTML('afterbegin',`<label class="field">选择认养对象<select name="adoptionId">${adoptionProjects.map(x=>`<option value="${x.id}">${x.short}</option>`).join('')}</select></label>`);const submit=f.onsubmit;f.onsubmit=e=>{const id=f.querySelector('[name="adoptionId"]').value,prev=new Set(state.approvals.map(a=>a.id));submit(e);state.approvals.filter(a=>!prev.has(a.id)).forEach(a=>a.adoptionId=id);save()}}return}
 visualBase.action(a,d);
 if(a==='village'){const a=$('#modal .art'),i=villages.findIndex(v=>v.id===d.id);if(a)a.innerHTML=photo(['village','bamboo','harvest'][i],photoLabels[['village','bamboo','harvest'][i]])}
 if(a==='event'){const ev=activities.find(x=>x.id===d.id),k=ev?.type==='自然户外'?'bamboo':ev?.type==='农事体验'?'harvest':'coffee',art=$('#modal .art');if(art)art.innerHTML=photo(k,photoLabels[k])}
};
// Reapply object illustrations after live search results are replaced.
const visualBind=bind;
bind=function(root=document){visualBind(root);if(root.id==='results')decorateScenes()};
render();

